//! Octant partition of two through holes generated by reflected meridians.
use super::*;

type Pair = [Vec<Point>; 2];

fn ordinate(p: Point, d: usize) -> Result<R, Error> {
    div(p[d], p[2])
}

fn meridians(x: &NurbsCurve2, z: &NurbsCurve2) -> Result<Vec<Pair>, Error> {
    let curves = [
        extract_bezier(x.degree, &x.knots, &x.controls)?,
        extract_bezier(z.degree, &z.knots, &z.controls)?,
    ];
    let mut breaks = BTreeSet::new();
    for curve in &curves {
        for span in curve {
            breaks.extend(span.interval);
        }
    }
    let breaks: Vec<_> = breaks.into_iter().collect();
    let mut out = Vec::new();
    for t in breaks.windows(2) {
        let mut pair: Pair = Default::default();
        for (net, curve) in pair.iter_mut().zip(&curves) {
            let span = curve
                .iter()
                .find(|s| s.interval[0] <= t[0] && s.interval[1] >= t[1])
                .ok_or("meridians need common parameter support")?;
            *net = restricted(span, [t[0], t[1]], x.degree.max(z.degree))?;
        }
        if pair[0].iter().zip(&pair[1]).any(|(a, b)| a[1..] != b[1..]) {
            return Err("unsynchronized meridian ordinate or weight");
        }
        out.push(pair);
    }
    if out.len() == 1 {
        let [x, z] = out.pop().unwrap();
        let (a, b) = split(&x, R::new(1, 2)?)?;
        let (c, d) = split(&z, R::new(1, 2)?)?;
        out.extend([[a, c], [b, d]]);
    }
    if out.len() < 2 {
        return Err("empty meridian");
    }
    for d in 0..2 {
        let first = &out[0][d];
        let last = &out.last().unwrap()[d];
        let n = last.len() - 1;
        if ordinate(first[0], 1)? != int(0)
            || ordinate(last[n], 0)? != int(0)
            || ordinate(first[0], 0)? != ordinate(first[1], 0)?
            || ordinate(last[n], 1)? != ordinate(last[n - 1], 1)?
        {
            return Err("meridian requires regular reflected endpoints");
        }
        for (i, pair) in out.iter().enumerate() {
            let net = &pair[d];
            let n = net.len() - 1;
            for w in net.windows(2) {
                if less(ordinate(w[0], 0)?, ordinate(w[1], 0)?)?
                    || less(ordinate(w[1], 1)?, ordinate(w[0], 1)?)?
                {
                    return Err("nonmonotone meridian controls");
                }
            }
            for k in [0, n - 1] {
                let strict = if i == 0 {
                    less(ordinate(net[k], 1)?, ordinate(net[k + 1], 1)?)?
                } else {
                    less(ordinate(net[k + 1], 0)?, ordinate(net[k], 0)?)?
                };
                if !strict {
                    return Err("uncertified regular meridian chart");
                }
            }
        }
    }
    Ok(out)
}

fn world(p: [R; 3], w: R, sign: [i64; 3], center: [i64; 3]) -> Result<[R; 4], Error> {
    let mut out = [w; 4];
    for i in 0..3 {
        out[i] = p[i]
            .checked_mul(int(sign[i]))?
            .checked_add(w.checked_mul(int(center[i]))?)?;
    }
    Ok(out)
}

/// Construct the material outside two intersecting extrusions of symmetric,
/// smooth-ended NURBS sections in a rectangular stock.
pub fn build_oval(
    bounds: [[i64; 2]; 3],
    center: [i64; 3],
    x: &NurbsCurve2,
    z: &NurbsCurve2,
) -> Result<Vec<BracketBlock>, Error> {
    let nets = meridians(x, z)?;
    let tip = nets[0][0].len() - 1;
    let seam = [
        ordinate(nets[0][0][tip], 0)?,
        ordinate(nets[0][0][tip], 1)?,
        ordinate(nets[0][1][tip], 0)?,
    ];
    if seam.iter().any(|a| a.numerator() <= 0) {
        return Err("degenerate meridian seam");
    }
    let size = [
        ordinate(nets[0][0][0], 0)?,
        ordinate(*nets.last().unwrap()[0].last().unwrap(), 1)?,
        ordinate(nets[0][1][0], 0)?,
    ];
    let mut blocks = Vec::new();
    for oct in 0..8 {
        let mut sign = [1; 3];
        let mut h = [int(0); 3];
        for i in 0..3 {
            let side = (oct >> i) & 1;
            sign[i] = 2 * side as i64 - 1;
            h[i] = int(bounds[i][side])
                .checked_sub(int(center[i]))?
                .checked_mul(int(sign[i]))?;
            if !less(size[i], h[i])? {
                return Err("meridian must lie strictly inside stock");
            }
        }
        let gx = div(h[0].checked_add(size[0])?, int(2))?;
        let gz = div(h[2].checked_add(size[2])?, int(2))?;
        let orientation = sign.iter().product::<i64>();
        for (i, pair) in nets.iter().enumerate() {
            for dominant in [0, 2] {
                let forward = (if dominant == 0 { 1 } else { -1 }) * orientation > 0;
                let mut net = Vec::new();
                for (a, b) in pair[0].iter().zip(&pair[1]) {
                    let w = a[2];
                    let inner = [a[0], a[1], b[0]];
                    let outer = if i == 0 {
                        [
                            gx.checked_mul(w)?,
                            div(h[1].checked_mul(a[1])?, seam[1])?,
                            gz.checked_mul(w)?,
                        ]
                    } else {
                        [
                            div(gx.checked_mul(a[0])?, seam[0])?,
                            h[1].checked_mul(w)?,
                            div(gz.checked_mul(b[0])?, seam[2])?,
                        ]
                    };
                    for p in [inner, outer] {
                        for upper in [false, true] {
                            let mut q = p;
                            if upper == forward {
                                q[dominant] = h[dominant].checked_mul(w)?;
                            }
                            net.push(world(q, w, sign, center)?);
                        }
                    }
                }
                blocks.push(BracketBlock {
                    id: format!("oval_{oct}_{i}_{dominant}"),
                    degrees: [pair[0].len() - 1, 1, 1],
                    controls: integer_net(&net)?,
                });
            }
        }
        let mut net = Vec::new();
        for xx in if orientation > 0 {
            [gx, h[0]]
        } else {
            [h[0], gx]
        } {
            for a in &nets[0][0] {
                let w = a[2];
                for zz in [gz, h[2]] {
                    net.push(world(
                        [
                            xx.checked_mul(w)?,
                            div(h[1].checked_mul(a[1])?, seam[1])?,
                            zz.checked_mul(w)?,
                        ],
                        w,
                        sign,
                        center,
                    )?);
                }
            }
        }
        blocks.push(BracketBlock {
            id: format!("oval_corner_{oct}"),
            degrees: [1, tip, 1],
            controls: integer_net(&net)?,
        });
    }
    Ok(blocks)
}
